                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 16 16"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <rect x="2.5" y="2" width="11" height="12" rx="2" />
                  <line x1="8" y1="5.5" x2="8" y2="10.5" />
                  <line x1="5.5" y1="8" x2="10.5" y2="8" />
                </svg>
              </button>
              <button
