  CardRelationPut,
  CardSummary,
  CardType,
  CleanupResult,
  ConceptGraphResponse,
  CurationStatus,
  DeletePreview,
  LinkStatus,
  MediaInfo,
  RelationPattern,
  RelationPatternCreate,
  RelationPatternPatch,
