def find_code_blocks(body: str) -> list[dict[str, Any]]:
    """以動態長度圍欄解析 Markdown 代碼塊，支援任意長度反引號或波浪號。"""
    pattern = re.compile(
r"^(?P<indent>[ \t]*)(?P<fence>`{3,}|~{3,})(?P<info>[^\n]*)\n(?:(?P<code>[\s\S]*?)\r?\n)?(?P=indent)(?P=fence)[ \t]*\r?$",
        re.MULTILINE,
    )
    blocks = []
    for m in pattern.finditer(body):
        code_val = m.group("code") or ""
        blocks.append({
            "start": m.start(),
            "end": m.end(),
            "fence": m.group("fence"),
            "info": m.group("info").strip(),
            "code": code_val,
        })
    return blocks


def block_label_name(block: dict[str, Any]) -> str:
    """代碼塊標籤的檔名（```tsx:Board.tsx → board.tsx）；沒有「:」標籤則回傳空字串。"""
    info = block["info"]
    if ":" not in info:
        return ""
    return Path(info.split(":", 1)[1].strip()).name.lower()


def select_block(blocks: list[dict[str, Any]], target_filename: str) -> dict[str, Any]:
    """標籤檔名完全相等優先；唯一且未標檔名的代碼塊才可使用；其餘一律報錯，不猜。"""
    want = target_filename.lower()
    matched = [b for b in blocks if block_label_name(b) == want]
    if len(matched) == 1:
        return matched[0]
    if len(matched) > 1:
        raise AppError(ErrorCode.VALIDATION_ERROR, f"有多個代碼塊都標註為「{target_filename}」，無法判定")
    if len(blocks) == 1 and not block_label_name(blocks[0]):
        return blocks[0]
    labels = [b["info"] or "（未標記）" for b in blocks]
    raise AppError(
        ErrorCode.VALIDATION_ERROR,
        f"找不到標註為「{target_filename}」的代碼塊；請在代碼塊標籤註明檔名（例如 python:{target_filename}）",
        {"available_labels": labels},
    )


def extract_target_code(body: str, target_filename: str) -> tuple[str, bool]:
    """從卡片提取代碼：優先匹配標籤包含目標檔名的代碼塊；無代碼塊或空代碼塊則拒絕寫入。"""
    blocks = find_code_blocks(body)
    if not blocks:
        raise AppError(ErrorCode.VALIDATION_ERROR, "卡片內沒有找到 Markdown 代碼塊，拒絕覆寫檔案")

    chosen = select_block(blocks, target_filename)

    code = chosen["code"]
    if not code.strip():
        raise AppError(ErrorCode.VALIDATION_ERROR, "選定的代碼塊為空，拒絕寫入空檔案")
    return code, True


def inject_target_code(original_body: str, target_filename: str, new_code: str) -> str:
    """將檔案內容安全注入卡片中匹配的代碼塊，動態擴增圍欄長度避免破壞 Markdown 結構。"""
    blocks = find_code_blocks(original_body)
    if not blocks:
        # 原卡片無代碼塊：保留原內文，把檔案內容以帶檔名標籤的代碼塊附在最後，不丟失任何原有文字
        backticks = "```"
        while backticks in new_code:
            backticks += "`"
        lang = Path(target_filename).suffix.lstrip(".") or "text"
        sep = "\n\n" if original_body.strip() else ""
        return f"{original_body.rstrip()}{sep}{backticks}{lang}:{target_filename}\n{new_code}\n{backticks}\n"

    chosen = select_block(blocks, target_filename)

    fence_char = chosen["fence"][0]
    max_consecutive = 0
    cur_count = 0
    for ch in new_code:
        if ch == fence_char:
            cur_count += 1
            if cur_count > max_consecutive:
                max_consecutive = cur_count
        else:
            cur_count = 0

    needed_len = max(len(chosen["fence"]), max_consecutive + 1, 3)
    new_fence = fence_char * needed_len
    new_block = f"{new_fence}{chosen['info']}\n{new_code}\n{new_fence}"
    return original_body[:chosen["start"]] + new_block + original_body[chosen["end"]:]


# 系統目錄黑名單：這是防手滑，不是安全邊界；真正的邊界是伺服器只綁 127.0.0.1、CORS 設白名單
_BLOCKED_DIRS: list[Path] = [
    Path(p) for p in ("/etc", "/proc", "/sys", "/dev", "/boot", "/bin", "/sbin", "/usr", "/lib", "/lib64")
]
for _env in ("SystemRoot", "ProgramFiles", "ProgramFiles(x86)", "ProgramData"):
    _val = os.environ.get(_env)
    if _val:
