@router.patch("/cards/{card_id}")
def patch_card(card_id: str, payload: CardPatch, request: Request):
    if (
        payload.title is None
        and payload.body is None
        and payload.card_type is None
        and payload.curation_status is None
        and payload.sources is None
        and payload.file_path is None
    ):
        raise AppError(ErrorCode.VALIDATION_ERROR, "至少要提供一個更新欄位")

    with session(request, write=True) as conn:
        row = conn.execute("SELECT * FROM cards WHERE id = ?", (card_id,)).fetchone()
        if row is None:
            raise AppError(ErrorCode.NOT_FOUND, "卡片不存在", {"card_id": card_id})
        if row["updated_at"] != payload.expected_updated_at:
            raise AppError(
                ErrorCode.STALE_VERSION,
                "這張卡片已在別處被修改，請重新載入後再儲存",
                {"current": card_detail(conn, card_id)},
            )

        title = payload.title if payload.title is not None else row["title"]
        body = payload.body if payload.body is not None else row["body"]
        card_type = payload.card_type.value if payload.card_type is not None else row["card_type"]
        curation_status = (
            payload.curation_status.value if payload.curation_status is not None else row["curation_status"]
        )
        sources = json.dumps(payload.sources, ensure_ascii=False) if payload.sources is not None else row["sources"]

        new_file_path = row["file_path"]
        new_file_hash = row["file_hash"]
        new_file_mtime = row["file_mtime"]

        if payload.file_path is not None:
            clean_path = payload.file_path.strip()
            if not clean_path:
                new_file_path = None
                new_file_hash = None
                new_file_mtime = None
            else:
                target_p = resolve_safe_path(clean_path)
                str_path = str(target_p)
                dup = conn.execute(
                    "SELECT id, title FROM cards WHERE file_path = ? AND id <> ?", (str_path, card_id)
                ).fetchone()
                if dup:
                    raise AppError(
                        ErrorCode.VALIDATION_ERROR,
                        f"該檔案已被卡片「{dup['title'] or dup['id']}」綁定，不可重複綁定",
                        {"conflict_card_id": dup["id"]},
                    )
                new_file_path = str_path
                # 綁定不等於同步：路徑有變才清空 hash/mtime，第一次寫入時若檔案已存在就會觸發 FILE_CONFLICT
                if str_path != row["file_path"]:
                    new_file_hash = None
                    new_file_mtime = None

        conn.execute(
            """UPDATE cards SET title = ?, body = ?, card_type = ?, curation_status = ?, sources = ?,
               file_path = ?, file_hash = ?, file_mtime = ?, updated_at = ?
               WHERE id = ?""",
            (title, body, card_type, curation_status, sources, new_file_path, new_file_hash, new_file_mtime, utc_now(), card_id),
        )
        return card_detail(conn, card_id)


@router.post("/cards/{card_id}/file/write")
def write_card_file(card_id: str, payload: CardFileWriteRequest, request: Request):
    """提取卡片匹配之代碼塊並安全寫入實體檔案。包含樂觀鎖、雜湊防呆、滾動備份與權限保留。"""
    with session(request, write=False) as conn:
        row = conn.execute("SELECT * FROM cards WHERE id = ?", (card_id,)).fetchone()
        if row is None:
            raise AppError(ErrorCode.NOT_FOUND, "卡片不存在", {"card_id": card_id})
        if row["updated_at"] != payload.expected_updated_at:
            raise AppError(
                ErrorCode.STALE_VERSION,
                "卡片已有更新內容尚未儲存，請先儲存卡片再寫入檔案",
                {"current": card_detail(conn, card_id)},
            )
        raw_path = row["file_path"]
        if not raw_path:
            raise AppError(ErrorCode.VALIDATION_ERROR, "此卡片尚未綁定本機檔案路徑")
        db_hash = row["file_hash"]
        body = row["body"]

    target = resolve_safe_path(raw_path)
    code_text, _ = extract_target_code(body, target.name)

    temp_file_path: Optional[Path] = None
    try:
        current_disk_bytes: Optional[bytes] = None
        current_disk_hash: Optional[str] = None
        if target.exists():
            if not target.is_file():
                raise AppError(ErrorCode.VALIDATION_ERROR, "目標路徑已存在但不是普通檔案")
            if target.stat().st_size > MAX_FILE_SIZE:
                raise AppError(ErrorCode.VALIDATION_ERROR, "目標檔案過大（超過 2MB），拒絕覆寫")
            current_disk_bytes = target.read_bytes()
            current_disk_hash = compute_file_hash(current_disk_bytes)

        # 保留原檔的 BOM、換行風格與「結尾有沒有換行」；新檔預設 LF、結尾有換行
        has_bom = bool(current_disk_bytes) and current_disk_bytes.startswith(b"\xef\xbb\xbf")
        use_crlf = bool(current_disk_bytes) and b"\r\n" in current_disk_bytes
        ends_with_eol = (not current_disk_bytes) or current_disk_bytes.endswith(b"\n")
        code_text = code_text.replace("\r\n", "\n")
        if ends_with_eol:
            code_text += "\n"
        if use_crlf:
            code_text = code_text.replace("\n", "\r\n")
        out_bytes = (b"\xef\xbb\xbf" if has_bom else b"") + code_text.encode("utf-8")

        # 內容完全相同：不寫檔、不建備份、不問衝突，只記下目前的同步狀態
        if current_disk_bytes is not None and current_disk_bytes == out_bytes:
            same_mtime = target.stat().st_mtime
            with session(request, write=True) as conn:
                save_file_state(conn, card_id, current_disk_hash, same_mtime)
            return {
                "success": True,
                "file_path": str(target),
                "file_hash": current_disk_hash,
                "mtime": same_mtime,
                "has_backup": False,
                "message": "檔案內容與卡片相同，無需寫入",
            }

        if current_disk_bytes is not None and not payload.force:
            if db_hash is None:
                raise AppError(
                    ErrorCode.FILE_CONFLICT,
                    "目標檔案已存在但卡片從未同步過，寫入將會覆蓋現有內容",
                    {"file_path": str(target)},
                )
            if current_disk_hash != db_hash:
                raise AppError(
                    ErrorCode.FILE_CONFLICT,
                    "目標檔案自上次同步後已被外部修改過，繼續寫入將覆蓋外部改動",
                    {"file_path": str(target)},
                )

        has_backup = False
        if target.exists() and current_disk_bytes is not None:
            latest_bak = get_latest_backup(target)
            need_backup = True
            if latest_bak and latest_bak.is_file():
                if compute_file_hash(latest_bak.read_bytes()) == current_disk_hash:
                    need_backup = False
            if need_backup:
                rotate_backups(target)
                has_backup = True

        with tempfile.NamedTemporaryFile("wb", dir=str(target.parent), delete=False) as tf:
            temp_file_path = Path(tf.name)
            tf.write(out_bytes)
            tf.flush()
            os.fsync(tf.fileno())

        if target.exists():
            try:
                shutil.copymode(target, temp_file_path)
            except OSError:
                pass
        else:
            try:
                os.chmod(temp_file_path, 0o644)  # 臨時檔預設 0600；新檔給一般原始碼檔的權限
            except OSError:
                pass

        os.replace(temp_file_path, target)
        temp_file_path = None

        new_hash = compute_file_hash(out_bytes)
        new_mtime = target.stat().st_mtime
    except (UnicodeEncodeError, UnicodeDecodeError) as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"檔案編碼處理失敗：{e}")
    except PermissionError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"存取檔案權限不足：{e}")
    except OSError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"檔案操作系統錯誤：{e}")
    finally:
        if temp_file_path and temp_file_path.exists():
            try:
                temp_file_path.unlink()
            except OSError:
                pass

    with session(request, write=True) as conn:
        conn.execute(
            "UPDATE cards SET file_hash = ?, file_mtime = ? WHERE id = ?",
            (new_hash, new_mtime, card_id),
        )

    return {
        "success": True,
        "file_path": str(target),
        "file_hash": new_hash,
        "mtime": new_mtime,
        "has_backup": has_backup,
        "message": "已成功寫入實體檔案",
    }


@router.post("/cards/{card_id}/file/read")
def read_card_file(card_id: str, request: Request):
    """從本機檔案讀取內容並更新至卡片匹配之代碼塊。"""
    with session(request, write=False) as conn:
        row = conn.execute("SELECT * FROM cards WHERE id = ?", (card_id,)).fetchone()
        if row is None:
            raise AppError(ErrorCode.NOT_FOUND, "卡片不存在", {"card_id": card_id})
        raw_path = row["file_path"]
        if not raw_path:
            raise AppError(ErrorCode.VALIDATION_ERROR, "此卡片尚未綁定本機檔案路徑")
        body = row["body"]
        base_updated_at = row["updated_at"]

    target = resolve_safe_path(raw_path)
    if not target.is_file():
        raise AppError(ErrorCode.NOT_FOUND, f"本機檔案不存在：{target}")

    try:
        st = target.stat()
        if st.st_size > MAX_FILE_SIZE:
            raise AppError(ErrorCode.VALIDATION_ERROR, "檔案過大（超過 2MB），拒絕讀入卡片")
        content_bytes = target.read_bytes()
        if b"\x00" in content_bytes:
            raise AppError(ErrorCode.VALIDATION_ERROR, "偵測到二進位字元，此檔案不是純文字程式碼")

        file_text = decode_text_file(content_bytes)

        new_hash = compute_file_hash(content_bytes)
        new_mtime = st.st_mtime
    except UnicodeDecodeError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"檔案解碼失敗（非 UTF-8 編碼）：{e}")
    except PermissionError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"無權限讀取檔案：{e}")
    except OSError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"讀取檔案失敗：{e}")

    new_body = inject_target_code(body, target.name, file_text)

    with session(request, write=True) as conn:
        apply_file_to_card(conn, card_id, base_updated_at, new_body, new_hash, new_mtime)
        return {
            "card": card_detail(conn, card_id),
            "mtime": new_mtime,
            "message": "已從檔案載入最新代碼",
        }


