          }}
          onClick={(e) => {
            e.stopPropagation();
            const segOffsetTop = hostRef.current?.offsetTop ?? 0;
            propsRef.current.onToggleLineMenu?.({
              lineTop: segOffsetTop + activeLine.top,
              lineBottom: segOffsetTop + activeLine.bottom,
            });
          }}
          title="點擊展開文字格式工具列"
          aria-label="文字格式工具列"
        >
          ::
        </button>
      )}
