test("中文：名稱與別名都能比對，count 與例句正確", () => {
  const r = findTagMentions("患者主訴踝麻，另有足/踝麻感，踝麻持續", TAGS, new Set());
  const t1 = r.find((m) => m.tag.id === "t1")!;
